import { useState } from "react";
import { BottomTabBar } from "@nativecn/ui/premium/mobile/bottom-tab-bar";
import { Home, Search, Bell, User } from "lucide-react-native";

export default function App() {
  const [active, setActive] = useState("home");
  const items = [
    { key: "home", label: "Home", icon: <Home size={20} /> },
    { key: "search", label: "Search", icon: <Search size={20} /> },
    { key: "alerts", label: "Alerts", icon: <Bell size={20} /> },
    { key: "profile", label: "Profile", icon: <User size={20} /> },
  ];
  return <BottomTabBar items={items} activeKey={active} onTabPress={setActive} />;
}
